      <p>Inactive Users: {inactiveUsers}</p>
      <p>Active Percentage: {activePercentage}%</p>
      <p style={{ display: 'none' }}>Active Percentage Detailed: {activePercentageDetailed}%</p>
    </div>
  )
}

